#include <stdio.h>

static int read_display(const int *view, int *display)
{
    if (display == NULL) {
        return -1;
    }
    if (view == NULL) {
        return 0;
    }
    *display = *view;
    return 1;
}

int main(void)
{
    int sensor = 31;
    const int *view = &sensor;
    int display = 17;

    int state = read_display(NULL, &display);
    printf("%d %d\n", state, display);

    sensor = 49;
    state = read_display(view, &display);
    printf("%d %d\n", state, display);
    return 0;
}

